/**
 * Telegram trading bot. Plain fetch() calls to the Bot API — no SDK
 * dependency, matching this codebase's existing style (Jupiter/deBridge/
 * Brave are all called the same way).
 *
 * Flow: /link <code> ties a Telegram chat to a wallet address (code is
 * generated by the authenticated /api/telegram/link-code endpoint in
 * index.js). A trade message is parsed via the existing /api/parse logic,
 * planned via planTrades, and shown back as a proposal the user must
 * confirm with "yes" before anything executes — mirroring the web app's
 * existing proposal/preview step. On confirm, each leg is signed via
 * Privy's server-side Wallet API (the user must have already granted this
 * via useDelegatedActions().delegateWallet() in the web app) and executed
 * through the exact same Jupiter order/execute path the web app uses.
 *
 * Chat↔wallet links are persisted (telegram_links in Postgres) since the
 * Strategy Agents evaluator needs to notify a linked chat potentially days
 * after the /link happened — a restart (i.e. every deploy) must not lose
 * that. linkCodes and pendingProposals stay in-memory deliberately: both
 * have short (single-digit-minute) TTLs, so losing them on a deploy just
 * means the user retries a still-fresh action, not a silent notification
 * gap days later.
 */
import { VersionedTransaction } from "@solana/web3.js";
import { derivePortfolio, planTrades } from "./portfolio.js";
import { upsertTelegramLink, getTelegramLinkForChat, getTelegramLinksForWallet } from "./db.js";
import { resolveSpotLegAmount, applyStrategyExecutionState } from "./strategyLegs.js";

const TELEGRAM_TOKEN = process.env.TELEGRAM_BOT_TOKEN || "";
const TELEGRAM_WEBHOOK_SECRET = process.env.TELEGRAM_WEBHOOK_SECRET || "";
const TELEGRAM_API = `https://api.telegram.org/bot${TELEGRAM_TOKEN}`;
const SOLANA_MAINNET_CAIP2 = "solana:5eykt4UsFv8P8NJdTREpY1vzqKqZKvdp";

if (!TELEGRAM_TOKEN) {
  console.warn("[telegram] TELEGRAM_BOT_TOKEN not set — bot endpoints are inert until it's configured.");
}

const LINK_CODE_TTL_MS = 10 * 60 * 1000; // 10 minutes
const PROPOSAL_TTL_MS = 5 * 60 * 1000; // 5 minutes

const linkCodes = new Map(); // code -> { address, expiresAt }
const pendingProposals = new Map(); // chatId (string) -> { trades, summary, address, expiresAt }

/** Called by the authenticated /api/telegram/link-code endpoint in index.js. */
export function generateLinkCode(address) {
  // Purge any existing code for this address so only the latest is valid.
  for (const [code, entry] of linkCodes) {
    if (entry.address === address) linkCodes.delete(code);
  }
  const code = String(Math.floor(100000 + Math.random() * 900000));
  linkCodes.set(code, { address, expiresAt: Date.now() + LINK_CODE_TTL_MS });
  return { code, expiresIn: LINK_CODE_TTL_MS / 1000 };
}

async function sendMessage(chatId, text) {
  if (!TELEGRAM_TOKEN) { console.warn("[telegram] can't send, no bot token:", text); return; }
  try {
    await fetch(`${TELEGRAM_API}/sendMessage`, {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({ chat_id: chatId, text }),
    });
  } catch (e) {
    console.error("[telegram] sendMessage failed:", e.message);
  }
}

/** Called by strategyAgents/evaluator.js whenever a strategy proposal is
 * created — messages every chat linked to that wallet (usually zero or
 * one, but never assumed to be exactly one; see telegram_links' own
 * comment in db.js). Best-effort: a wallet with no linked chat is a
 * normal, silent no-op, not an error. */
export async function notifyStrategyProposal(walletAddress, text) {
  const chatIds = await getTelegramLinksForWallet(walletAddress);
  for (const chatId of chatIds) await sendMessage(chatId, text);
}

async function handleLink(chatId, code) {
  if (!code) { await sendMessage(chatId, "Usage: /link 123456 — get a code from My Profile → Settings in the app."); return; }
  const entry = linkCodes.get(code);
  if (!entry || entry.expiresAt < Date.now()) {
    await sendMessage(chatId, "That code is invalid or expired. Generate a new one in the app (My Profile → Settings).");
    return;
  }
  await upsertTelegramLink({ chatId: String(chatId), walletAddress: entry.address });
  linkCodes.delete(code);
  await sendMessage(
    chatId,
    `Linked to wallet ${entry.address.slice(0, 4)}…${entry.address.slice(-4)}.\n\n` +
    `You can now send trade requests here, e.g. "sell my BTC for cash". I'll show you the plan and wait for you to reply YES before executing anything real.\n\n` +
    `One more thing needed before trades can actually execute: enable "Bot Trading" in My Profile → Settings, which lets the server sign trades on your behalf (revocable anytime, Privy still holds your keys).`
  );
}

async function handleTradeRequest(deps, chatId, address, text) {
  const { bySymbol } = await deps.getRegistry();
  const holdings = await deps.getHoldingsForAddress(address);
  const mints = Object.values(bySymbol).filter((t) => t.symbol !== "USDC").map((t) => t.mint);
  const prices = await deps.getPricesForMints(mints);
  const portfolio = derivePortfolio(holdings, prices, bySymbol, {});
  const current = portfolio.rows.map((r) => ({ symbol: r.symbol, weight: r.weight }));

  const { allocations, summary } = await deps.parsePromptToAllocations({ prompt: text, current, total: portfolio.total });
  const { trades, maxSkippedDelta } = planTrades({ allocations, portfolio, prices, registry: bySymbol });

  if (!trades.length) {
    await sendMessage(chatId, maxSkippedDelta > 0
      ? `That change is too small to execute (largest leg ~$${maxSkippedDelta.toFixed(2)}, minimum $0.25).`
      : `${summary}\n\nNo trades needed — you're already there.`);
    return;
  }

  pendingProposals.set(String(chatId), { trades, summary, address, expiresAt: Date.now() + PROPOSAL_TTL_MS });
  const lines = trades.map((t) => `${t.side === "buy" ? "Buy" : "Sell"} $${t.usd.toFixed(2)} ${t.symbol}`);
  await sendMessage(chatId, `${summary}\n\n${lines.join("\n")}\n\nReply YES to confirm or NO to cancel (expires in 5 min).`);
}

async function handleConfirm(deps, chatId) {
  const pending = pendingProposals.get(String(chatId));
  if (!pending || pending.expiresAt < Date.now()) {
    pendingProposals.delete(String(chatId));
    await sendMessage(chatId, "No pending trade to confirm (or it expired) — send a new request.");
    return;
  }
  pendingProposals.delete(String(chatId));

  if (!deps.privyClient) {
    await sendMessage(chatId, "Bot trading isn't configured on the server yet (missing Privy credentials). Contact the app owner.");
    return;
  }

  // TEMPORARY diagnostic for the auth-signature failures — logs to Railway
  // logs only (never sent to the chat or any HTTP response). Remove once resolved.
  try {
    const wallets = await deps.privyClient.walletApi.getWallets({ chainType: "solana", limit: 100 });
    const match = wallets.data.find((w) => w.address === pending.address);
    console.log(`[telegram/confirm] delegation check for ${pending.address}:`, match
      ? { ownerId: match.ownerId, additionalSigners: match.additionalSigners, policyIds: match.policyIds }
      : "wallet not found in Privy's walletApi.getWallets() list");
  } catch (diagErr) {
    console.error("[telegram/confirm] delegation check failed:", diagErr?.message || diagErr);
  }

  await sendMessage(chatId, "Executing…");
  for (const leg of pending.trades) {
    try {
      const order = await deps.buildOrder({
        inputMint: leg.inputMint, outputMint: leg.outputMint,
        amount: String(leg.amount), taker: pending.address,
      });

      // Sign only (don't sign-and-send) — executeSignedOrder needs to route
      // through Jupiter's own execute endpoint for RFQ orders, or straight
      // to Solana RPC for the AMM-fallback path; it already knows how to do
      // both correctly, so we reuse it unchanged rather than duplicating
      // that logic with signAndSendTransaction.
      const tx = VersionedTransaction.deserialize(Buffer.from(order.transaction, "base64"));
      const { signedTransaction } = await deps.privyClient.walletApi.solana.signTransaction({
        address: pending.address,
        chainType: "solana",
        transaction: tx,
      });
      const signedB64 = Buffer.from(signedTransaction.serialize()).toString("base64");

      const result = await deps.executeSignedOrder({
        signedTransaction: signedB64,
        requestId: order.requestId,
        sponsored: order._sponsored,
        swapV1: order._swapV1,
        isSell: order._isSell,
      });

      if (result.status && result.status !== "Success") {
        await sendMessage(chatId, `❌ ${leg.side} $${leg.usd.toFixed(2)} ${leg.symbol} failed: ${result.error || result.status}`);
      } else {
        await sendMessage(chatId, `✅ ${leg.side === "buy" ? "Bought" : "Sold"} $${leg.usd.toFixed(2)} ${leg.symbol} — https://solscan.io/tx/${result.signature}`);
      }
    } catch (e) {
      // Privy throws a specific error if the wallet was never delegated —
      // surface that plainly rather than a generic failure.
      const msg = e instanceof Error ? e.message : String(e);
      console.error(`[telegram/confirm] leg failed for ${pending.address}:`, e?.response?.data || e?.cause || e);
      await sendMessage(chatId, `❌ ${leg.side} $${leg.usd.toFixed(2)} ${leg.symbol} failed: ${msg}`);
    }
  }
}

/**
 * Confirms one Strategy Agents proposal, addressed explicitly by ID
 * ("YES 42") rather than the bare "YES" handleConfirm uses — a strategy
 * proposal lives in Postgres with its own 24h TTL (not the 5-minute
 * in-memory pendingProposals map above), and a chat could plausibly have
 * more than one strategy proposal outstanding at once, so an unqualified
 * "YES" would be ambiguous. getProposal's own wallet-ownership check
 * (id + walletAddress) is what stops a linked chat from confirming a
 * proposal that isn't actually its wallet's. Mirrors handleConfirm's
 * build → sign (Privy walletApi) → execute sequence, then performs the
 * exact same three effects /api/strategies/proposals/:id/report-execution
 * does on the web path (markProposalConfirmed, logActivity as kind:"swap"
 * so it counts toward referral volume, touchStrategyEvaluated) so a trade
 * confirmed via Telegram is indistinguishable, downstream, from one
 * confirmed in the app.
 */
async function handleStrategyConfirm(deps, chatId, proposalId) {
  const link = await getTelegramLinkForChat(String(chatId));
  if (!link) return; // webhook handler already gates on `link` before calling this
  const proposal = await deps.getProposal(proposalId, link.address);
  if (!proposal) { await sendMessage(chatId, `No pending proposal #${proposalId} for your wallet.`); return; }
  if (proposal.status !== "pending") { await sendMessage(chatId, `Proposal #${proposalId} is already ${proposal.status}.`); return; }
  if (new Date(proposal.expires_at) < new Date()) { await sendMessage(chatId, `Proposal #${proposalId} has expired.`); return; }

  // Single-leg spot proposals only (dca_buy, delta_neutral_rebalance,
  // twap_slice, vwap_slice) — delta_neutral_open/exit carry a SECOND perp
  // leg this handler has no way to execute, so it must refuse the whole
  // proposal rather than silently executing just the spot half of a
  // position that's supposed to be hedged (a naked, unhedged buy is a
  // materially different and riskier thing than what was proposed).
  const leg = proposal.legs[0];
  if (proposal.legs.length !== 1 || !leg || leg.domain !== "spot") {
    await sendMessage(chatId, "This proposal type isn't supported via Telegram yet — confirm it in the app.");
    return;
  }
  if (!deps.privyClient) {
    await sendMessage(chatId, "Bot trading isn't configured on the server yet (missing Privy credentials). Contact the app owner.");
    return;
  }

  await sendMessage(chatId, "Executing…");
  try {
    // Same amount resolution the web /build route uses — leg.amount is
    // DCA's precomputed convention; delta-neutral/TWAP/VWAP legs carry
    // `usd`/`sellAll` instead and resolve their real atomic amount from
    // live holdings/prices right here (see strategyLegs.js).
    const amount = await resolveSpotLegAmount(leg, link.address, {
      getHoldingsForAddress: deps.getHoldingsForAddress, getPricesForMints: deps.getPricesForMints,
    });
    const order = await deps.buildOrder({
      inputMint: leg.inputMint, outputMint: leg.outputMint,
      amount, taker: link.address,
    });
    const tx = VersionedTransaction.deserialize(Buffer.from(order.transaction, "base64"));
    const { signedTransaction } = await deps.privyClient.walletApi.solana.signTransaction({
      address: link.address, chainType: "solana", transaction: tx,
    });
    const signedB64 = Buffer.from(signedTransaction.serialize()).toString("base64");

    const result = await deps.executeSignedOrder({
      signedTransaction: signedB64,
      requestId: order.requestId, sponsored: order._sponsored,
      swapV1: order._swapV1, isSell: order._isSell,
    });
    if (result.status && result.status !== "Success") {
      await sendMessage(chatId, `❌ ${proposal.summary} failed: ${result.error || result.status}`);
      return;
    }

    await deps.markProposalConfirmed(proposalId, [result.signature]);
    deps.logActivity({
      walletAddress: link.address, kind: "swap",
      symbol: leg.symbol, side: leg.side, usdValue: leg.usd, signature: result.signature,
      details: { inputMint: leg.inputMint, outputMint: leg.outputMint, amount, feeBps: order.feeBps ?? null, strategyId: proposal.strategy_id, proposalId: proposal.id },
    });
    // Same kind-based state update the web /report-execution route uses —
    // NOT always "lastExecutedAt" (that's DCA-only; delta-neutral/TWAP/VWAP
    // each advance their own state differently, see strategyLegs.js).
    // order.inAmount/outAmount (Jupiter's raw order response, already in
    // scope here) power TWAP/VWAP execution-quality tracking the same way
    // the web confirm path forwards them.
    await applyStrategyExecutionState(
      proposal, link.address,
      order.inAmount && order.outAmount ? { inAmount: order.inAmount, outAmount: order.outAmount } : null,
      {
        touchStrategyEvaluated: deps.touchStrategyEvaluated, setStrategyStatus: deps.setStrategyStatus,
        getStrategyById: deps.getStrategyById, getRegistry: deps.getRegistry,
      },
    );

    await sendMessage(chatId, `✅ ${proposal.summary} — https://solscan.io/tx/${result.signature}`);
  } catch (e) {
    const msg = e instanceof Error ? e.message : String(e);
    console.error(`[telegram/strategy-confirm] leg failed for ${link.address}:`, e?.response?.data || e?.cause || e);
    await sendMessage(chatId, `❌ ${proposal.summary} failed: ${msg}`);
  }
}

async function handleStrategyReject(deps, chatId, proposalId) {
  const link = await getTelegramLinkForChat(String(chatId));
  if (!link) return;
  const proposal = await deps.getProposal(proposalId, link.address);
  if (!proposal || proposal.status !== "pending") {
    await sendMessage(chatId, `No pending proposal #${proposalId} for your wallet.`);
    return;
  }
  await deps.markProposalRejected(proposalId);
  await sendMessage(chatId, `Rejected proposal #${proposalId}.`);
}

/**
 * Mounts the webhook route on the given Express app. `deps` carries the
 * pieces already defined in index.js (registry, holdings/prices, order
 * building/execution, and the Privy client) so this module doesn't need a
 * circular import back into index.js.
 */
export function mountTelegramRoutes(app, deps) {
  app.post("/api/telegram/webhook", async (req, res) => {
    // Telegram sends this header on every webhook call once configured via
    // setWebhook's secret_token param — verifies the request actually came
    // from Telegram, not someone who found the URL.
    if (TELEGRAM_WEBHOOK_SECRET) {
      const got = req.headers["x-telegram-bot-api-secret-token"];
      if (got !== TELEGRAM_WEBHOOK_SECRET) return res.status(401).end();
    }
    res.status(200).end(); // ack immediately — Telegram doesn't wait for our reply message

    const msg = req.body?.message;
    if (!msg || !msg.text) return;
    const chatId = msg.chat.id;
    const text = msg.text.trim();

    try {
      if (text === "/start") {
        await sendMessage(chatId, "Welcome to Bonzai Trading. Get a linking code from My Profile → Settings in the app, then send /link <code> here.");
        return;
      }
      if (text.startsWith("/link")) {
        await handleLink(chatId, text.split(/\s+/)[1]);
        return;
      }

      const link = await getTelegramLinkForChat(String(chatId));
      if (!link) {
        await sendMessage(chatId, "Your Telegram isn't linked to a wallet yet. Get a code from My Profile → Settings in the app, then send /link <code>.");
        return;
      }

      // Bare YES/NO stays scoped to the freeform trade flow above
      // (pendingProposals, 5-min TTL) — "YES 42"/"NO 42" targets a
      // specific Strategy Agents proposal ID instead, since a chat can
      // have more than one of those outstanding (each with its own 24h
      // TTL in Postgres) and an unqualified reply would be ambiguous.
      const yesMatch = text.match(/^(?:yes|y|confirm)\s*(\d+)?$/i);
      const noMatch = text.match(/^(?:no|n|cancel)\s*(\d+)?$/i);
      if (yesMatch) {
        if (yesMatch[1]) await handleStrategyConfirm(deps, chatId, yesMatch[1]);
        else await handleConfirm(deps, chatId);
        return;
      }
      if (noMatch) {
        if (noMatch[1]) { await handleStrategyReject(deps, chatId, noMatch[1]); return; }
        pendingProposals.delete(String(chatId));
        await sendMessage(chatId, "Cancelled.");
        return;
      }

      await handleTradeRequest(deps, chatId, link.address, text);
    } catch (e) {
      console.error("[telegram] handler error:", e);
      await sendMessage(chatId, `Something went wrong: ${e instanceof Error ? e.message : String(e)}`);
    }
  });
}
